-- ============================================================
-- SES — DEV-ONLY seed: CONTRACT_V snapshot
-- Run after 03_request_ddl.sql. See README.md for full run order.
--
-- WARNING: This script is for LOCAL DEVELOPMENT ONLY.
-- In production, CONTRACT_V is a VIEW granted (read-only) from
-- another database — see extracted-contract-v.sql (the DDL/data
-- extract this seed is derived from, via
-- extracted-contract-v-standalone.sql) and
-- ses/sql/22_emp_nik_view_dev_seed.sql for the same convention.
-- SES never writes to CONTRACT_V.
--
-- This dev script CREATES a local snapshot TABLE named CONTRACT_V
-- (matching the production view's shape: NO_KONTRAK, COMPANY,
-- JUDUL_PEKERJAAN, TANGGAL_MULAI, TANGGAL_SELESAI) so the request
-- form's Contract Number autofill (ContractVRepository) has a
-- source to search locally.
--
-- NEVER run this against a schema where CONTRACT_V is a real view
-- or where other apps depend on it.
--
-- ContractV.noKontrak is this table's JPA @Id, so rows are deduped
-- by NO_KONTRAK (first occurrence kept) versus the raw extract —
-- the source dump carried ~44 near-duplicate rows per contract
-- (identical data, timestamp-of-export noise only), which would
-- otherwise let Hibernate's session identity map silently collapse
-- rows with mismatched field values.
-- ============================================================

BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE CONTRACT_V PURGE';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

CREATE TABLE CONTRACT_V (
  NO_KONTRAK       VARCHAR2(20),
  COMPANY          VARCHAR2(200),
  JUDUL_PEKERJAAN  VARCHAR2(1000),
  TANGGAL_MULAI    TIMESTAMP,
  TANGGAL_SELESAI  TIMESTAMP
);

